// Illuminated Christmas Tree Assembly
// Standalone Canvas 2D animation. No dependencies, assets, DOM or runtime clock.
// Time Motion Studio: time is SECONDS. One continuous 20-second seamless loop.
// Native video export target: 3840 x 2160, 60 fps, 20 seconds, minimum 100 Mbps.
// Bitrate is configured in the video encoder, not in the Canvas drawing API.
// All lighting is solid color / clipped surface shading. No blur or glow effects.
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0) || !Number.isFinite(t)) return;
  const TAU = Math.PI * 2;
  const phase = sceneProgress * TAU;
  const unit = Math.min(width / 1600, minSide / 900);
  const offsetX = (width - 1600 * unit) * 0.5;
  const offsetY = (height - 900 * unit) * 0.5;
  const P = {
    ivory: '#F7F3E9', paper: '#FFFCF4', cream: '#E6DBBF',
    navy: '#172F39', deep: '#11282E', slate: '#4E6670',
    green: '#24644D', pine: '#163E32', mint: '#92B7A0',
    red: '#B43E40', berry: '#792F37', blush: '#E5B4A6',
    gold: '#CAA363', goldLight: '#E9D0A1', goldDark: '#96703D',
    cocoa: '#613E30', wood: '#A87B58', ice: '#DCE7E7'
  };
  const clamp = v => Math.max(0, Math.min(1, v));
  const sm = v => { const u = clamp(v); return u * u * u * (u * (u * 6 - 15) + 10); };
  const mix = (a, b, v) => a + (b - a) * v;
  const mod = (a, b) => ((a % b) + b) % b;
  const wave = (n = 1, o = 0) => Math.sin(phase * n + o);
  const cycle = (start, length) => {
    const u = mod(loopT - start, duration) / length;
    return u < 1 ? 0.5 - 0.5 * Math.cos(TAU * u) : 0;
  };
  const hash = n => { const a = Math.sin(n * 127.1 + 311.7) * 43758.5453123; return a - Math.floor(a); };
  const shade = (hex, factor = 0.82) => '#' + [1, 3, 5].map(i => Math.min(255, Math.round(parseInt(hex.slice(i, i + 2), 16) * factor)).toString(16).padStart(2, '0')).join('');
  const gradient = (x, y, w, h, a, b) => {
    const g = ctx.createLinearGradient(x, y, x + w, y + h);
    g.addColorStop(0, a); g.addColorStop(1, b); return g;
  };
  function line(x1, y1, x2, y2, color, weight = 2) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = weight; ctx.stroke();
  }
  function poly(points, fill, stroke, weight = 2) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke, weight = 2) {
    ctx.beginPath(); ctx.ellipse(x, y, Math.max(0.001, rx), Math.max(0.001, ry), 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }
  const circle = (x, y, r, fill, stroke, weight = 2) => ellipse(x, y, r, r, fill, stroke, weight);
  function rounded(x, y, w, h, radius) {
    const r = Math.min(radius, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r); ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h); ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r); ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function rr(x, y, w, h, r, fill, stroke, weight = 2) {
    rounded(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = weight; ctx.stroke(); }
  }
  function at(x, y, angle, scale, paint) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); ctx.scale(scale, scale); paint(); ctx.restore();
  }
  function star(x, y, radius, color, angle = -Math.PI / 2, inset = 0.45) {
    const pts = [];
    for (let i = 0; i < 10; i++) {
      const a = angle + i * Math.PI / 5, r = i % 2 ? radius * inset : radius;
      pts.push([x + Math.cos(a) * r, y + Math.sin(a) * r]);
    }
    poly(pts, color);
  }
  function snowflake(x, y, size, color, angle = 0, weight = 2) {
    at(x, y, angle, 1, () => {
      for (let i = 0; i < 6; i++) {
        const a = i * TAU / 6, dx = Math.cos(a), dy = Math.sin(a);
        line(0, 0, dx * size, dy * size, color, weight);
        for (const u of [0.48, 0.74]) {
          const x1 = dx * size * u, y1 = dy * size * u;
          for (const d of [-1, 1]) {
            const b = a + d * Math.PI / 3;
            line(x1, y1, x1 - Math.cos(b) * size * 0.21, y1 - Math.sin(b) * size * 0.21, color, weight);
          }
        }
      }
    });
  }
  function leaf(x, y, length, breadth, angle, color) {
    at(x, y, angle, 1, () => {
      ctx.beginPath(); ctx.moveTo(0, 0);
      ctx.bezierCurveTo(length * 0.28, -breadth, length * 0.8, -breadth * 0.52, length, 0);
      ctx.bezierCurveTo(length * 0.7, breadth * 0.63, length * 0.25, breadth * 0.77, 0, 0);
      ctx.fillStyle = color; ctx.fill();
    });
  }
  function sprig(x, y, length, angle = 0, color = P.pine) {
    at(x, y, angle, 1, () => {
      line(0, 0, length, 0, color, 2.6);
      for (let i = 1; i < 9; i++) {
        const q = length * i / 10, l = length * (0.26 - i * 0.015);
        leaf(q, 0, l, 3.4, -0.75, i % 2 ? color : P.green);
        leaf(q, 0, l, 3.4, 0.75, i % 2 ? color : P.green);
      }
    });
  }
  function holly(x, y, s = 1, angle = 0) {
    at(x, y, angle, s, () => {
      leaf(0, 0, 49, 14, -0.8, P.green);
      leaf(0, 0, 48, 14, 0.3, P.pine);
      leaf(0, 0, 37, 12, 2.1, P.green);
      circle(-2, -3, 8, P.red); circle(12, 1, 7.5, P.berry); circle(4, 11, 7.3, P.red);
      circle(-4, -5, 2, P.blush); circle(10, -1, 1.8, P.blush);
    });
  }
  function cone(x, y, s = 1, angle = 0) {
    at(x, y, angle, s, () => {
      ellipse(0, 0, 21, 35, P.cocoa);
      for (let row = 0; row < 5; row++) {
        const yy = -24 + row * 12, span = 15 * Math.sin((row + 1) * Math.PI / 6);
        for (let col = 0; col < 3; col++) {
          ellipse((col - 1) * span, yy, 8.5, 6.5, row % 2 ? P.wood : '#BB8C64', P.cocoa, 1.2);
        }
      }
    });
  }
  function bow(x, y, s = 1, color = P.red, angle = 0) {
    at(x, y, angle, s, () => {
      poly([[-6, 5], [-39, 77], [-17, 66], [-3, 79], [9, 12]], color);
      poly([[5, 8], [15, 73], [31, 59], [51, 66], [16, 2]], color);
      ctx.beginPath(); ctx.moveTo(-7, 0);
      ctx.bezierCurveTo(-81, -65, -104, 0, -54, 20); ctx.bezierCurveTo(-25, 31, -13, 11, -7, 0);
      ctx.fillStyle = color; ctx.fill();
      ctx.beginPath(); ctx.moveTo(7, 0);
      ctx.bezierCurveTo(81, -65, 104, 0, 54, 20); ctx.bezierCurveTo(25, 31, 13, 11, 7, 0);
      ctx.fill();
      ctx.beginPath(); ctx.moveTo(-67, -12); ctx.quadraticCurveTo(-39, -19, -13, 0);
      ctx.moveTo(67, -12); ctx.quadraticCurveTo(39, -19, 13, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.20)'; ctx.lineWidth = 4; ctx.stroke();
      rr(-13, -11, 26, 26, 7, color); line(-5, -7, -5, 9, 'rgba(255,255,255,0.22)', 3);
    });
  }
  function gift(x, y, w, h, color = P.red, ribbon = P.goldLight, lift = 0) {
    const side = Math.min(24, w * 0.14);
    poly([[x + w, y - h], [x + w + side, y - h - 12], [x + w + side, y - 12], [x + w, y]], shade(color, 0.70));
    rr(x, y - h, w, h, 3, gradient(x, y - h, w, h, color, shade(color, 0.83)));
    rr(x + w * 0.44, y - h, w * 0.14, h, 0, ribbon);
    for (let i = 0; i < 3; i++) line(x + 13, y - h + 24 + i * 29, x + 24, y - h + 24 + i * 29, 'rgba(255,255,255,0.18)', 2);
    const topY = y - h - lift;
    poly([[x - 4, topY], [x + 18, topY - 13], [x + w + side + 4, topY - 13], [x + w + 4, topY]], shade(color, 1.08));
    rr(x - 4, topY, w + 8, 20, 3, color, 'rgba(0,0,0,0.10)', 1.5);
    rr(x + w * 0.44, topY, w * 0.14, 20, 0, ribbon);
    bow(x + w * 0.51, topY - 3, Math.min(0.7, w / 240), ribbon);
  }
  function bauble(x, y, r, color = P.red, style = 0) {
    rr(x - r * 0.19, y - r - 8, r * 0.38, 12, 3, P.gold);
    circle(x, y, r, gradient(x - r, y - r, r * 2, r * 2, shade(color, 1.08), shade(color, 0.75)), 'rgba(0,0,0,0.12)', 1.5);
    ctx.save(); circle(x, y, r - 1); ctx.clip();
    if (style % 3 === 0) {
      for (let i = -1; i <= 1; i++) {
        ctx.beginPath(); ctx.moveTo(x - r, y + i * r * 0.34);
        ctx.quadraticCurveTo(x, y + i * r * 0.34 + r * 0.2, x + r, y + i * r * 0.34);
        ctx.strokeStyle = P.goldLight; ctx.lineWidth = Math.max(2, r * 0.045); ctx.stroke();
      }
    } else if (style % 3 === 1) snowflake(x, y, r * 0.62, P.goldLight, 0, Math.max(1.8, r * 0.035));
    else {
      for (let i = 0; i < 7; i++) {
        const a = i * TAU / 7; star(x + Math.cos(a) * r * 0.58, y + Math.sin(a) * r * 0.58, r * 0.1, P.goldLight);
      }
      star(x, y, r * 0.27, P.goldLight);
    }
    ctx.beginPath(); ctx.ellipse(x - r * 0.31, y - r * 0.35, r * 0.12, r * 0.3, 0.65, 0, TAU);
    ctx.fillStyle = 'rgba(255,255,255,0.23)'; ctx.fill(); ctx.restore();
  }
  function pineTree(x, ground, scale = 1, snowCap = false, color = P.green) {
    at(x, ground, 0, scale, () => {
      rr(-12, -80, 24, 84, 3, P.wood);
      for (let k = 0; k < 4; k++) {
        const yy = -110 - k * 72, w = 130 - k * 22;
        ctx.beginPath(); ctx.moveTo(0, yy - 155); ctx.lineTo(w, yy + 14);
        ctx.quadraticCurveTo(0, yy + 47, -w, yy + 14); ctx.closePath();
        ctx.fillStyle = k % 2 ? color : P.pine; ctx.fill();
        if (snowCap) {
          ctx.beginPath(); ctx.moveTo(0, yy - 155); ctx.lineTo(w * 0.54, yy - 63);
          ctx.quadraticCurveTo(12, yy - 36, 0, yy - 53); ctx.quadraticCurveTo(-17, yy - 38, -w * 0.54, yy - 63);
          ctx.closePath(); ctx.fillStyle = P.ice; ctx.fill();
        }
      }
    });
  }
  function floorShadow(x, y, w, h = 18) { ellipse(x, y, w, h, 'rgba(15,35,35,0.10)'); }
  function background(top = P.ivory, bottom = P.cream, floor = true) {
    rr(0, 0, 1600, 900, 0, gradient(0, 0, 0, 900, top, bottom));
    if (floor) {
      rr(0, 732, 1600, 168, 0, 'rgba(255,255,255,0.22)');
      line(70, 732, 1530, 732, 'rgba(30,50,45,0.12)', 1.5);
    }
  }
  function frame(color = 'rgba(100,120,105,0.22)') {
    rr(56, 48, 1488, 804, 16, null, color, 1.2);
    for (const x of [86, 1514]) for (const y of [78, 822]) circle(x, y, 3, color);
  }
  function snow(x, y, w, h, count = 55, color = P.paper, seed = 0) {
    ctx.save(); rr(x, y, w, h, 0); ctx.clip();
    for (let i = 0; i < count; i++) {
      const k = i + seed * 107, size = 1.6 + hash(k + 0.8) * 3.8;
      const yy = mod(hash(k + 2) * h + sceneProgress * h * (i % 3 === 0 ? 2 : 1), h);
      const xx = 18 + hash(k + 1) * (w - 36) + wave(1, k) * (3 + hash(k + 3) * 8);
      const alpha = sm(yy / 30) * sm((h - yy) / 30) * (0.28 + hash(k + 4) * 0.5);
      ctx.globalAlpha = alpha; circle(x + xx, y + yy, size, color);
    }
    ctx.restore();
  }
  function candle(x, base, w, h, color = P.ivory, seed = 0) {
    rr(x - w / 2, base - h, w, h, 8, gradient(x - w / 2, base - h, w, 0, color, color === P.ivory ? '#D7CEB4' : color));
    ellipse(x, base - h, w / 2, 9, '#E6DCC4');
    ellipse(x, base - h + 1, w * 0.28, 4.5, '#C6B895'); line(x, base - h - 2, x, base - h - 13, P.cocoa, 3);
    const lean = wave(7, seed) * 3, tall = 36 + wave(9, seed) * 3;
    ctx.beginPath(); ctx.moveTo(x, base - h - 12);
    ctx.bezierCurveTo(x - 18, base - h - 21, x - 9 + lean, base - h - tall, x + lean, base - h - tall - 17);
    ctx.bezierCurveTo(x + 9 + lean, base - h - tall, x + 16, base - h - 20, x, base - h - 12);
    ctx.fillStyle = P.gold; ctx.fill();
    ellipse(x + lean * 0.35, base - h - 25, 5, 10, P.goldLight);
  }
  function lantern(x, y, s = 1) {
    at(x, y, 0, s, () => {
      rr(-31, -93, 62, 88, 5, P.goldLight, P.navy, 5);
      poly([[-40, -94], [0, -122], [40, -94]], P.navy);
      rr(-42, -10, 84, 12, 3, P.navy); line(0, -92, 0, -12, P.navy, 3);
      circle(0, -132, 9, null, P.navy, 3); candle(0, -15, 18, 37, P.ivory, x * 0.01);
    });
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.setLineDash([]); ctx.lineDashOffset = 0;
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)'; ctx.filter = 'none';
  ctx.fillStyle = P.ivory; ctx.fillRect(0, 0, width, height);
  ctx.translate(offsetX, offsetY); ctx.scale(unit, unit);
  ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.save(); rr(0, 0, 1600, 900, 0); ctx.clip();
  background('#F1F3E7', '#DCE5D9');
  rr(155, 155, 310, 490, 18, 'rgba(255,255,255,0.22)', 'rgba(50,88,69,0.12)', 2);
  for (let i = 0; i < 3; i++) line(180, 218 + i * 129, 440, 218 + i * 129, '#CAD6C6', 1.5);
  rr(1143, 190, 278, 388, 9, P.paper, P.green, 9);
  ctx.save(); rr(1156, 203, 252, 362, 3); ctx.clip();
  rr(1156, 203, 252, 362, 0, '#C5D9D5');
  pineTree(1196, 592, 0.55, true, '#547C69'); pineTree(1375, 579, 0.48, true, '#718F7D');
  snow(1156, 203, 252, 362, 27, P.paper, 4); ctx.restore();
  line(1282, 203, 1282, 565, P.green, 7); line(1156, 382, 1408, 382, P.green, 7);
  rr(1130, 581, 304, 17, 4, P.green);
  floorShadow(800, 795, 299, 25);
  at(803, 753, 0, 1.06, () => {
    ctx.save(); ctx.scale(1.24, 1); pineTree(0, 0, 1, false); ctx.restore();
    const rows = [[-377, 40], [-298, 76], [-208, 111], [-118, 146]];
    for (let j = 0; j < rows.length; j++) {
      const [yy, span] = rows[j];
      ctx.beginPath(); ctx.moveTo(-span, yy); ctx.quadraticCurveTo(0, yy + 43, span, yy);
      ctx.strokeStyle = P.gold; ctx.lineWidth = 3.1; ctx.stroke();
      for (let k = 0; k < 7; k++) {
        const u = k / 6, xx = mix(-span, span, u), bulbY = yy + 86 * u * (1 - u);
        circle(xx, bulbY, 4.8, P.goldDark);
        ctx.save(); ctx.globalAlpha = 0.65 + 0.2 * wave(2, j + k * 0.7); circle(xx, bulbY, 3.5, P.goldLight); ctx.restore();
      }
    }
    const ornaments = [[-26,-341,15],[40,-344,13],[-72,-253,18],[71,-254,18],[0,-242,16],[-117,-163,18],[116,-158,18],[-56,-97,19],[54,-94,17]];
    for (let i = 0; i < ornaments.length; i++) {
      const [xx, yy, r] = ornaments[i];
      at(xx, yy - 18, wave(1, i) * 0.027, 1, () => { line(0, 0, 0, 16, P.goldDark, 1.5); bauble(0, 28, r, i % 2 ? P.gold : P.red, i); });
    }
    star(0, -488, 29, P.gold, -Math.PI / 2 + wave(1) * 0.018);
    star(-5, -493, 9, P.goldLight);
  });
  gift(496, 800, 134, 107, P.red, P.goldLight);
  gift(663, 812, 138, 145, P.green, P.goldLight);
  gift(835, 812, 125, 100, P.gold, P.ivory);
  gift(993, 800, 104, 131, P.red, P.ivory);
  at(311, 352, wave(1) * 0.01, 1, () => {
    circle(0, 0, 81, null, P.pine, 15);
    for (let i = 0; i < 12; i++) { const a = i * TAU / 12; sprig(Math.cos(a) * 77, Math.sin(a) * 77, 44, a + 1.3); }
    bow(0, 74, 0.4, P.red);
  });
  lantern(298, 790, 0.75);
  cone(1260, 750, 0.8, 0.45); holly(1320, 782, 1.25, -1.1); frame();
  ctx.restore();
  ctx.restore();
}

